{
  "$schema": "https://www.schemastore.org/claude-code-marketplace.json",
  "name": "akm-claude-plugins",
  "description": "akm のチーム共有 Claude Code プラグイン集",
  "owner": {
    "name": "akm"
  },
  "plugins": [
    {
      "name": "commit-rules-guard",
      "description": "コミットルールを想起させ、動機の混在を気づかせるフック集 (セッション開始時・作業着手時・計画作成時・git commit 直前)",
      "author": {
        "name": "akm"
      },
      "category": "development",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/akm/claude-plugins",
        "path": "commit-rules-guard",
        "ref": "main"
      },
      "tags": ["git", "commit", "hooks", "workflow"]
    },
    {
      "name": "pr-teeth",
      "description": "GitHub の PR を噛み砕いて解説する。レビュー依頼の巡回と、番号や URL で指定した PR (マージ済みも可) の解説に対応し、リポジトリ別のレビュー範囲に照らした解説を HTML で作る (出力言語は設定可能、既定は日本語)",
      "author": {
        "name": "akm"
      },
      "category": "development",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/akm/claude-plugins",
        "path": "pr-teeth",
        "ref": "main"
      },
      "tags": ["github", "pull-request", "review", "i18n", "skills"]
    },
    {
      "name": "mermaid-preview",
      "description": "mermaid の図を含む HTML を生成してブラウザで見せる skill (他のスキルからの図の提示にも使う)",
      "author": {
        "name": "akm"
      },
      "category": "development",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/akm/claude-plugins",
        "path": "mermaid-preview",
        "ref": "main"
      },
      "tags": ["mermaid", "diagram", "documentation", "skill"]
    },
    {
      "name": "commit-squash",
      "description": "未 push のコミットを、同じ関心事のものどうしでまとめて数を減らす skill (rebase を使わず起点から積み直す)",
      "author": {
        "name": "akm"
      },
      "category": "development",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/akm/claude-plugins",
        "path": "commit-squash",
        "ref": "main"
      },
      "tags": ["git", "commit", "history", "skill"]
    },
    {
      "name": "doc-dag",
      "description": "文書群のセクション単位の依存と重複を調べ、mermaid 図で示して DAG になるよう修正する skill",
      "author": {
        "name": "akm"
      },
      "category": "development",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/akm/claude-plugins",
        "path": "doc-dag",
        "ref": "main"
      },
      "tags": ["documentation", "dag", "mermaid", "skill"]
    },
    {
      "name": "work-log-gh-comment",
      "description": "実行したコマンドと出力を、機密を伏せたうえで省略せずに GitHub の Issue / PR へ記録する skill",
      "author": {
        "name": "akm"
      },
      "category": "development",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/akm/claude-plugins",
        "path": "work-log-gh-comment",
        "ref": "main"
      },
      "tags": ["github", "logging", "documentation", "skill"]
    },
    {
      "name": "review-triage",
      "description": "レビュー指摘を採択 / 保留 / 却下に選り分け、採択したものを原因で束ねて直し、レビューから修正までを上限回数まで回す (レビューは sub-agent か端末のワーカーか、別のセッションで実行する) skill 6 つと、レビューを行うワーカーのスクリプト、修正フェーズを sub-agent で実行する agent 定義、記録を検査する Go ツール",
