input.command:
cat ~/.claude/plugins/known_marketplaces.json | head -60; echo '---'; python3 -c "
import json,os
d=json.load(open(os.path.expanduser('~/.claude/plugins/installed_plugins.json')))
print('version', d.get('version'))
p=d.get('plugins',d)
for k,v in p.items():
  if 'akm' in k:
    print(k)
    for e in v: print('  ', json.dumps(e, ensure_ascii=False))
"

