def outcome_line(progress):
    """中止・中断したときの、処理中だったものの状態を示す行を返す (R15・R17・KTD8)。"""
    if progress.updating:
        return f"処理中だったもの: マーケットプレイス {progress.marketplace} の定義の取得し直し"
    target = progress.current
